 b.n(4,'ارتفاع سطح آب پس از جابه‌جایی حجم',t,f'کرهٔ شعاع {a} کاملاً در استوانهٔ شعاع {2*a} فرو می‌رود؛ سطح آب چند واحد بالا می‌آید؟ π در نسبت حذف می‌شود.',F(a,3),'حجم آب جابه‌جا شده برابر حجم کره و برابر مساحت قاعدهٔ ظرف در افزایش ارتفاع است.',f'(Rational(4,3)*pi*{a}**3)/(pi*({2*a})**2)')
 b.n(4,'نسبت عددی حجم به مساحت کره',r,f'برای کرهٔ شعاع {3*a}، نسبت عدد حجم به عدد مساحت در یک واحد طول ثابت چند است؟',a,'با تقسیم دو فرمول، چهار پی و توان دوم شعاع حذف می‌شوند؛ نسبت r/3 می‌ماند.',f'(Rational(4,3)*pi*({3*a})**3)/(4*pi*({3*a})**2)')
 b.n(4,'حجم مخروط از شعاع و مولد',p,f'شعاع مخروط {3*k} و مولد {5*k} است؛ حجم با π=3 چند است؟',36*k**3,'اول ارتفاع عمودی را با فیثاغورس به دست آور؛ مولد را مستقیم در فرمول حجم نگذار.',f'3*({3*k})**2*sqrt(({5*k})**2-({3*k})**2)/3')
 b.n(4,'ارتفاع هرم مربع از ارتفاع وجه',p,f'ضلع قاعدهٔ هرم منتظم مربع {6*k} و ارتفاع وجه جانبی {5*k} است؛ ارتفاع عمودی هرم چند است؟',4*k,'در مثلث قائمِ مقطع، نصف ضلع قاعده و ارتفاع عمودی دو ضلع قائمه‌اند.',f'sqrt(({5*k})**2-({3*k})**2)')
 b.n(4,'تبدیل حجم بین واحدهای مکعب',t,f'حجم {a} متر مکعب چند سانتی‌متر مکعب است؟',a*10**6,'هر متر صد سانتی‌متر است؛ برای حجم ضریب تبدیل باید مکعب شود.',f'{a}*100**3')
 b.n(4,'دوران ربع دایره حول شعاع',t,f'ربع دایرهٔ شعاع {a} را حول یکی از دو شعاع مرزش دوران می‌دهیم؛ حجم جسم چند است؟ π=3.',2*a**3,'جسم حاصل نیم‌کره است؛ دوران نیم‌دایره حول قطر کرهٔ کامل می‌دهد.',f'Rational(2,3)*3*{a}**3')
 b.n(4,'تفاوت دو محور دوران مستطیل',t,f'مستطیل با ضلع‌های {a} و {a+2} یک بار حول ضلع {a} و بار دیگر حول ضلع {a+2} دوران می‌کند؛ نسبت حجم اول به دوم چند است؟',F(a+2,a),'در هر دوران، ضلع محور ارتفاع و ضلع دیگر شعاع است؛ هر دو حجم را جدا بنویس.',f'(pi*({a+2})**2*{a})/(pi*{a}**2*{a+2})')
 b.n(4,'ارتفاع مخروط با حجم برابر کره',p,f'مخروط و کره‌ای هر دو شعاع {a} دارند و حجمشان برابر است؛ ارتفاع مخروط چند است؟',4*a,'دو فرمول حجم را برابر بگذار و عامل مشترک پی و مربع شعاع را حذف کن.',f'(Rational(4,3)*pi*{a}**3)*3/(pi*{a}**2)')
 b.n(4,'برش هرم با صفحهٔ موازی و نسبت حجم',p,f'هرمی با صفحهٔ موازی قاعده بریده شده و ارتفاع هرم کوچکِ رأس، نصف ارتفاع هرم اصلی است؛ حجم هرم کوچک چه کسری از حجم اصلی است؟',F(1,8),'همهٔ طول‌های متناظر نصف‌اند؛ حجم با مکعب نسبت طول تغییر می‌کند؛ این تمرین تکمیلی است.', 'Rational(1,2)**3')
 b.n(4,'مساحت گستردهٔ هرم منتظم مثلثی',p,f'هرم منتظم چهاروجهی با یال {2*a}، چهار وجه مثلث متساوی‌الاضلاع دارد؛ مساحت کل را c√3 می‌نویسیم؛ c چند است؟',4*a*a,'مساحت هر مثلث متساوی‌الاضلاع یک چهارم مربع ضلع در رادیکال سه است؛ چهار وجه را جمع کن.',f'(4*(sqrt(3)/4)*({2*a})**2)/sqrt(3)')
 b.essay(2,'توجیه واحدها و انتخاب فرمول سطح',r,'برای ساخت روکش یک توپ و برای تعیین گنجایش آن، چرا دو فرمول متفاوت لازم است؟','روکش به مساحت سطح و واحد مربع نیاز دارد؛ گنجایش به حجم و واحد مکعب. برای کره، S=4πr² و V=4πr³/3.',['فرق اندازهٔ دوبعدی و سه‌بعدی.','دو فرمول و واحد درست.'])
 b.essay(3,'رسم گستردهٔ هرم مربع',p,'گسترده‌ای برای یک هرم منتظم با قاعدهٔ مربع رسم کن و قاعده و وجه‌های جانبی را مشخص کن.','یک مربع و چهار مثلث متساوی‌الساقینِ هم‌اندازه، هرکدام متصل به یکی از ضلع‌های مربع، یک گستردهٔ معتبر می‌سازند.',['یک مربع برای قاعده.','چهار مثلث جانبی سازگار.','اتصال درست بدون هم‌پوشانی.'])
 b.essay(3,'حل مرحله‌ای مخروط با مولد',p,'مخروطی با شعاع 3 و مولد 5 داریم؛ ارتفاع و حجم آن را با π=3 حساب کن.','ارتفاع √(25−9)=4 و حجم 3×9×4/3=36 است.',['فیثاغورس و ارتفاع.','فرمول حجم.','جایگذاری، پاسخ و واحد.'])
 b.essay(4,'تحلیل سطح خارجی جسم مرکب',t,'استوانه‌ای با یک نیم‌کره روی آن داریم؛ توضیح بده چرا نمی‌توان مساحت کل دو جسم جدا را بدون اصلاح جمع کرد.','دایرهٔ بالای استوانه و کف نیم‌کره روی هم و داخل جسم قرار می‌گیرند؛ در سطح خارجی دیده نمی‌شوند و نباید دوبار شمرده شوند.',['تشخیص سطح تماس.','تفکیک سطح‌های بیرونی.','حذف درست سطح‌های داخلی.'])
 b.essay(4,'استدلال تغییر حجم نسبت به طول',r,'چرا با دو برابر شدن شعاع کره، حجم هشت برابر ولی مساحت چهار برابر می‌شود؟','در فرمول مساحت، شعاع توان دو دارد و ضریب تغییر 2²=4 است؛ در حجم، توان سه دارد و ضریب 2³=8 است.',['دو فرمول یا وابستگی به توان.','دو ضریب و تفسیر.'])
 for q in b.rows:
  adjusted={'تبدیل حجم بین واحدهای مکعب': 2}.get(q['objective'])
  if adjusted:q['level']=adjusted;q['difficulty']=LEVELS[adjusted-1]
 return b.finish()
